<script setup>
import {ref,watch,computed} from 'vue';
const props=defineProps({modelValue:{type:String,default:'#ffffff'}}),emit=defineEmits(['update:modelValue']);
const hue=ref(0),sat=ref(0),value=ref(1),hex=ref(props.modelValue);
watch(()=>props.modelValue,color=>{if(!/^#[0-9a-f]{6}$/i.test(color))return;hex.value=color;const [r,g,b]=[1,3,5].map(i=>parseInt(color.slice(i,i+2),16)/255),max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min;value.value=max;sat.value=max?d/max:0;if(d)hue.value=((max===r?(g-b)/d+(g<b?6:0):max===g?(b-r)/d+2:(r-g)/d+4)*60);},{immediate:true});
const hueColor=computed(()=>`hsl(${hue.value},100%,50%)`);
function publish(){const h=hue.value/60,c=value.value*sat.value,x=c*(1-Math.abs(h%2-1)),m=value.value-c;const rgb=h<1?[c,x,0]:h<2?[x,c,0]:h<3?[0,c,x]:h<4?[0,x,c]:h<5?[x,0,c]:[c,0,x];emit('update:modelValue','#'+rgb.map(n=>Math.round((n+m)*255).toString(16).padStart(2,'0')).join(''));}
function move(e){if(e.type==='pointermove'&&!e.currentTarget.hasPointerCapture(e.pointerId))return;if(e.type==='pointerdown')e.currentTarget.setPointerCapture(e.pointerId);const r=e.currentTarget.getBoundingClientRect();sat.value=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width));value.value=1-Math.max(0,Math.min(1,(e.clientY-r.top)/r.height));publish();}
function key(e){const k=e.key;if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(k))return;e.preventDefault();sat.value=Math.max(0,Math.min(1,sat.value+(k==='ArrowRight'?.02:k==='ArrowLeft'?-.02:0)));value.value=Math.max(0,Math.min(1,value.value+(k==='ArrowUp'?.02:k==='ArrowDown'?-.02:0)));publish();}
const swatches=['#ffffff','#ffcb80','#ff574a','#ff40ae','#a066ff','#408cff','#30d6df','#71ed81'];
</script>
<template><div class="paint-palette"><div class="paint-square" tabindex="0" role="slider" aria-label="颜色饱和度和明度，左右及上下方向键调整" :aria-valuetext="modelValue" :style="{backgroundColor:hueColor}" @pointerdown.prevent="move" @pointermove.prevent="move" @keydown="key"><span :style="{left:sat*100+'%',top:(1-value)*100+'%',background:modelValue}"></span></div><label class="paint-hue">色相<input aria-label="色相" type="range" min="0" max="359" v-model.number="hue" @input="publish"></label><div class="paint-swatches"><button v-for="c in swatches" :key="c" :aria-label="'颜色 '+c" :style="{background:c}" @click="emit('update:modelValue',c)"></button></div><label class="paint-hex"><i :style="{background:modelValue}"></i><input aria-label="十六进制颜色" v-model="hex" maxlength="7" @change="/^#[0-9a-f]{6}$/i.test(hex)?emit('update:modelValue',hex):hex=modelValue"></label></div></template>
